#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  EDirect eDir;  int r;  int fr;  RGBTRIPLE rgb[2];//0-центр,1-край  } Queue_Circle;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void SetT(RGBTRIPLE& val,COLORREF color);//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintCircle(DefinePaint)  {  QueueP(Queue_Circle);  int w = p->W()/2;  int h = p->H()/2;  int m = min(w,h);  //  if ( w == h )// круг    {    RECT rect = p->mRect;    for ( int n = 0; n < m; n++ )      {      //      COLORREF color = Col(p->rgb[1],p->rgb[0],n,m);      CMyRgn rgn( hDC, color );      rgn.Ellipse( rect );      if ( p->eDir == dirFree )        ::InflateRect( &rect, -1, -1 );      else      if ( p->eDir == dirHorz )        ::InflateRect( &rect, -1, 0 );      else      if ( p->eDir == dirVert )        ::InflateRect( &rect, 0, -1 );      }    }  else  if ( w > h ) // приплюснутый эллипис    {    RECT rect = p->mRect;    for ( int n = 0; n < m; n++ )      {      //      COLORREF color = Col(p->rgb[1],p->rgb[0],n,m);      CMyRgn rgn( hDC, color );      rgn.Ellipse( rect );        int d = MulDiv(n+1,w,m);      rect = p->mRect;      if ( p->eDir == dirFree )        ::InflateRect( &rect, -d, -(n+1) );      else      if ( p->eDir == dirHorz )        ::InflateRect( &rect, -d, 0 );      else      if ( p->eDir == dirVert )        ::InflateRect( &rect, 0, -(n+1) );      //      }    }  else  if ( w < h ) // вытянутый эллипис    {    RECT rect = p->mRect;    for ( int n = 0; n < m; n++ )      {      //      COLORREF color = Col(p->rgb[1],p->rgb[0],n,m);      CMyRgn rgn( hDC, color );      rgn.Ellipse( rect );        int d = MulDiv(n+1,h,m);      rect = p->mRect;      if ( p->eDir == dirFree )        ::InflateRect( &rect, -(n+1), -d );      else      if ( p->eDir == dirHorz )        ::InflateRect( &rect, -(n+1), 0 );      else      if ( p->eDir == dirVert )        ::InflateRect( &rect, 0, -d );      //      }    }  //  if ( p->fr > 0 )    {    CMyPen arc( hDC, 0, p->fr );    ::Arc( hDC, p->mRect.left, p->mRect.top, p->mRect.right, p->mRect.bottom,                p->mRect.right+1,10000,p->mRect.left-1,10000 );    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddCircle(DefineTegs)  {  AddQueueEx(Queue_Circle);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintCircle;  //  POINT pt = {0,0};  COLORREF light = 0xffffff;//0-центр  COLORREF dark  = 0x000000;//1-край  //  STegObj obj[] =    {    { 'R', "rect"  , &p->mRect },    { 'E', "rc"    , &p->mRect },    { 'P', "pt"    , &pt    },    { 'I', "r"     , &p->r  },    { 'I', "radius", &p->r  },    { 'A', "light" , &light },    { 'A', "dark"  , &dark  },    { 'A', "l"     , &light },    { 'A', "d"     , &dark  },    { 'I', "frame" , &p->fr },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  p->eDir = ParserDirect(teg[0].value);  SetT(p->rgb[0],light);  SetT(p->rgb[1],dark );  //  if ( p->r > 0 )    ::SetRect(&p->mRect,pt.x-p->r,pt.y-p->r,pt.x+p->r,pt.y+p->r);  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~